CREATE TABLE IF NOT EXISTS products(id VARCHAR(64) PRIMARY KEY,name VARCHAR(120) NOT NULL,type VARCHAR(16) NOT NULL,price INT NOT NULL CHECK(price>0),stock INT NOT NULL CHECK(stock>=0),reserved INT DEFAULT 0 NOT NULL CHECK(reserved>=0),sold INT DEFAULT 0 NOT NULL,category VARCHAR(64),scene VARCHAR(32),brand VARCHAR(64),description VARCHAR(2000),spec TEXT,image VARCHAR(500),status VARCHAR(16) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bundle_parts(bundle_id VARCHAR(64) NOT NULL,item_id VARCHAR(64) NOT NULL,quantity INT NOT NULL CHECK(quantity>0),PRIMARY KEY(bundle_id,item_id));
CREATE TABLE IF NOT EXISTS reservations(order_id VARCHAR(64) PRIMARY KEY,status VARCHAR(16) NOT NULL,request_json TEXT NOT NULL,quote_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reservation_lines(order_id VARCHAR(64) NOT NULL,item_id VARCHAR(64) NOT NULL,quantity INT NOT NULL,PRIMARY KEY(order_id,item_id));